"""SQLite persistence layer for the inventory service."""
import sqlite3
import datetime


def now():
    return datetime.datetime.utcnow().isoformat()


def get_conn(path=":memory:"):
    conn = sqlite3.connect(path, check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.row_factory = sqlite3.Row
    return conn


SCHEMA = """
CREATE TABLE IF NOT EXISTS warehouses(
    id TEXT PRIMARY KEY, name TEXT, location TEXT, created_at TEXT
);
CREATE TABLE IF NOT EXISTS products(
    id TEXT PRIMARY KEY, name TEXT, unit TEXT, created_at TEXT
);
CREATE TABLE IF NOT EXISTS stock_levels(
    warehouse_id TEXT, product_id TEXT, quantity INTEGER NOT NULL DEFAULT 0,
    threshold INTEGER, version INTEGER NOT NULL DEFAULT 0, updated_at TEXT,
    PRIMARY KEY(warehouse_id, product_id)
);
CREATE TABLE IF NOT EXISTS global_settings(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS stock_adjustments(
    id TEXT PRIMARY KEY, warehouse_id TEXT, product_id TEXT, change_type TEXT,
    delta INTEGER, quantity_before INTEGER, quantity_after INTEGER,
    reason TEXT, actor TEXT, idempotency_key TEXT, created_at TEXT
);
CREATE TABLE IF NOT EXISTS alerts(
    id TEXT PRIMARY KEY, warehouse_id TEXT, product_id TEXT, threshold INTEGER,
    quantity_at_trigger INTEGER, status TEXT, created_at TEXT, resolved_at TEXT
);
CREATE TABLE IF NOT EXISTS idempotency_keys(
    key TEXT PRIMARY KEY, endpoint TEXT, request_hash TEXT,
    response_body TEXT, status_code INTEGER, created_at TEXT
);
CREATE TABLE IF NOT EXISTS api_keys(
    key TEXT PRIMARY KEY, owner TEXT, role TEXT, created_at TEXT
);
"""


def init_db(conn):
    conn.executescript(SCHEMA)
    conn.execute(
        "INSERT OR IGNORE INTO global_settings(key, value) VALUES('default_low_stock_threshold','10')"
    )
    conn.execute(
        "INSERT OR IGNORE INTO api_keys(key, owner, role, created_at) VALUES('test-key','admin','admin',?)",
        (now(),),
    )
    conn.commit()
    return conn

"""Core business logic: warehouses, products, stock, thresholds, alerts, audit."""
import uuid
import json
from . import db


class ServiceError(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.message = message
        self.status = status


class InventoryService:
    def __init__(self, conn):
        self.conn = conn

    def _new_id(self, prefix):
        return f"{prefix}-{uuid.uuid4().hex[:12]}"

    def check_api_key(self, key):
        if not key:
            return False
        row = self.conn.execute("SELECT 1 FROM api_keys WHERE key=?", (key,)).fetchone()
        return row is not None

    def create_warehouse(self, name, location):
        wid = self._new_id("wh")
        ts = db.now()
        self.conn.execute(
            "INSERT INTO warehouses(id,name,location,created_at) VALUES(?,?,?,?)",
            (wid, name, location, ts),
        )
        self.conn.commit()
        return {"id": wid, "name": name, "location": location, "created_at": ts}

    def list_warehouses(self):
        rows = self.conn.execute("SELECT id,name,location FROM warehouses").fetchall()
        return [dict(r) for r in rows]

    def create_product(self, name, unit):
        pid = self._new_id("pr")
        ts = db.now()
        self.conn.execute(
            "INSERT INTO products(id,name,unit,created_at) VALUES(?,?,?,?)",
            (pid, name, unit, ts),
        )
        self.conn.commit()
        return {"id": pid, "name": name, "unit": unit, "created_at": ts}

    def list_products(self):
        rows = self.conn.execute("SELECT id,name,unit FROM products").fetchall()
        return [dict(r) for r in rows]

    def _default_threshold(self):
        row = self.conn.execute(
            "SELECT value FROM global_settings WHERE key='default_low_stock_threshold'"
        ).fetchone()
        return int(row["value"]) if row else None

    def add_stock(self, warehouse_id, product_id, quantity, threshold=None):
        if quantity is None or quantity < 0:
            raise ServiceError("quantity must be a non-negative number")
        wh = self.conn.execute("SELECT id FROM warehouses WHERE id=?", (warehouse_id,)).fetchone()
        pr = self.conn.execute("SELECT id FROM products WHERE id=?", (product_id,)).fetchone()
        if not wh or not pr:
            raise ServiceError("warehouse or product not found", 404)
        existing = self.conn.execute(
            "SELECT * FROM stock_levels WHERE warehouse_id=? AND product_id=?",
            (warehouse_id, product_id),
        ).fetchone()
        if existing:
            raise ServiceError("stock already exists; use adjustments", 409)
        ts = db.now()
        self.conn.execute(
            "INSERT INTO stock_levels(warehouse_id,product_id,quantity,threshold,version,updated_at)"
            " VALUES(?,?,?,?,0,?)",
            (warehouse_id, product_id, quantity, threshold, ts),
        )
        self.conn.commit()
        return {
            "warehouse_id": warehouse_id,
            "product_id": product_id,
            "quantity": quantity,
            "threshold": threshold,
            "version": 0,
        }

    def set_threshold(self, warehouse_id, product_id, threshold):
        row = self.conn.execute(
            "SELECT * FROM stock_levels WHERE warehouse_id=? AND product_id=?",
            (warehouse_id, product_id),
        ).fetchone()
        if not row:
            raise ServiceError("stock record not found", 404)
        self.conn.execute(
            "UPDATE stock_levels SET threshold=? WHERE warehouse_id=? AND product_id=?",
            (threshold, warehouse_id, product_id),
        )
        self.conn.commit()
        return {"warehouse_id": warehouse_id, "product_id": product_id, "threshold": threshold}

    def get_stock(self, warehouse_id, product_id):
        row = self.conn.execute(
            "SELECT * FROM stock_levels WHERE warehouse_id=? AND product_id=?",
            (warehouse_id, product_id),
        ).fetchone()
        if not row:
            raise ServiceError("stock record not found", 404)
        return dict(row)

    def get_stock_by_product(self, product_id):
        rows = self.conn.execute(
            "SELECT warehouse_id,quantity,threshold FROM stock_levels WHERE product_id=?",
            (product_id,),
        ).fetchall()
        return [dict(r) for r in rows]

    def get_stock_by_warehouse(self, warehouse_id):
        rows = self.conn.execute(
            "SELECT product_id,quantity,threshold FROM stock_levels WHERE warehouse_id=?",
            (warehouse_id,),
        ).fetchall()
        return [dict(r) for r in rows]

    def list_alerts(self):
        rows = self.conn.execute(
            "SELECT * FROM alerts WHERE status='ACTIVE' ORDER BY created_at DESC"
        ).fetchall()
        return [dict(r) for r in rows]

    def list_audit(self):
        rows = self.conn.execute(
            "SELECT * FROM stock_adjustments ORDER BY created_at DESC"
        ).fetchall()
        return [dict(r) for r in rows]

    def _idem_lookup(self, key):
        if not key:
            return None
        row = self.conn.execute(
            "SELECT response_body FROM idempotency_keys WHERE key=?", (key,)
        ).fetchone()
        return json.loads(row["response_body"]) if row else None

    def _idem_store(self, key, endpoint, response, status_code):
        if not key:
            return
        self.conn.execute(
            "INSERT OR REPLACE INTO idempotency_keys(key,endpoint,request_hash,response_body,"
            "status_code,created_at) VALUES(?,?,?,?,?,?)",
            (key, endpoint, "", json.dumps(response), status_code, db.now()),
        )

    def adjust_stock(self, warehouse_id, product_id, change_type, amount, reason=None,
                      actor="system", idempotency_key=None):
        cached = self._idem_lookup(idempotency_key)
        if cached is not None:
            return cached
        if amount is None or not isinstance(amount, (int, float)):
            raise ServiceError("amount is required and must be numeric")
        row = self.conn.execute(
            "SELECT * FROM stock_levels WHERE warehouse_id=? AND product_id=?",
            (warehouse_id, product_id),
        ).fetchone()
        if not row:
            raise ServiceError("stock record not found", 404)
        qty_before = row["quantity"]
        version = row["version"]
        ct = (change_type or "").upper()
        if ct == "INCREMENT":
            qty_after, delta = qty_before + amount, amount
        elif ct == "DECREMENT":
            qty_after, delta = qty_before - amount, -amount
        elif ct == "SET":
            qty_after, delta = amount, amount - qty_before
        else:
            raise ServiceError("invalid change_type; use INCREMENT/DECREMENT/SET")
        if qty_after < 0:
            raise ServiceError("adjustment would result in negative stock", 409)
        cur = self.conn.execute(
            "UPDATE stock_levels SET quantity=?, version=version+1, updated_at=? "
            "WHERE warehouse_id=? AND product_id=? AND version=?",
            (qty_after, db.now(), warehouse_id, product_id, version),
        )
        if cur.rowcount == 0:
            raise ServiceError("concurrent modification detected, retry", 409)
        adj_id = self._new_id("adj")
        self.conn.execute(
            "INSERT INTO stock_adjustments(id,warehouse_id,product_id,change_type,delta,"
            "quantity_before,quantity_after,reason,actor,idempotency_key,created_at) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            (adj_id, warehouse_id, product_id, ct, delta, qty_before, qty_after,
             reason, actor, idempotency_key, db.now()),
        )
        threshold = row["threshold"]
        if threshold is None:
            threshold = self._default_threshold()
        alert_triggered = False
        if threshold is not None and qty_after <= threshold:
            active = self.conn.execute(
                "SELECT id FROM alerts WHERE warehouse_id=? AND product_id=? AND status='ACTIVE'",
                (warehouse_id, product_id),
            ).fetchone()
            if not active:
                aid = self._new_id("al")
                self.conn.execute(
                    "INSERT INTO alerts(id,warehouse_id,product_id,threshold,quantity_at_trigger,"
                    "status,created_at,resolved_at) VALUES(?,?,?,?,?,'ACTIVE',?,NULL)",
                    (aid, warehouse_id, product_id, threshold, qty_after, db.now()),
                )
            alert_triggered = True
        else:
            self.conn.execute(
                "UPDATE alerts SET status='RESOLVED', resolved_at=? "
                "WHERE warehouse_id=? AND product_id=? AND status='ACTIVE'",
                (db.now(), warehouse_id, product_id),
            )
        response = {
            "adjustment_id": adj_id,
            "warehouse_id": warehouse_id,
            "product_id": product_id,
            "quantity_before": qty_before,
            "quantity_after": qty_after,
            "alert_triggered": alert_triggered,
        }
        self._idem_store(idempotency_key, "/v1/stock/adjustments", response, 201)
        self.conn.commit()
        return response

"""HTTP API layer built on stdlib http.server with simple regex routing."""
import json
import re
from http.server import BaseHTTPRequestHandler
from .service import ServiceError

METRICS = {"requests": 0, "errors": 0}
ROUTES = []


def route(method, pattern):
    regex = re.compile("^" + pattern + "$")

    def deco(fn):
        ROUTES.append((method, regex, fn))
        return fn
    return deco


def make_handler(service):
    class Handler(BaseHTTPRequestHandler):
        def _send(self, code, payload):
            body = json.dumps(payload).encode()
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _auth(self):
            auth = self.headers.get("Authorization", "")
            key = auth.replace("Bearer ", "").strip()
            return service.check_api_key(key)

        def _body(self):
            length = int(self.headers.get("Content-Length", 0) or 0)
            if length == 0:
                return {}
            return json.loads(self.rfile.read(length))

        def _dispatch(self, method):
            METRICS["requests"] += 1
            path = self.path.split("?")[0]
            if path == "/metrics":
                self._send(200, METRICS)
                return
            if not self._auth():
                METRICS["errors"] += 1
                self._send(401, {"error": "unauthorized"})
                return
            for m, regex, fn in ROUTES:
                if m != method:
                    continue
                match = regex.match(path)
                if match:
                    try:
                        body = self._body() if method in ("POST", "PUT") else {}
                        result, code = fn(service, match.groups(), body)
                        self._send(code, result)
                    except ServiceError as e:
                        METRICS["errors"] += 1
                        self._send(e.status, {"error": e.message})
                    except Exception as e:
                        METRICS["errors"] += 1
                        self._send(400, {"error": str(e)})
                    return
            METRICS["errors"] += 1
            self._send(404, {"error": "not found"})

        def do_GET(self):
            self._dispatch("GET")

        def do_POST(self):
            self._dispatch("POST")

        def do_PUT(self):
            self._dispatch("PUT")

        def log_message(self, fmt, *args):
            pass

    return Handler


@route("POST", r"/v1/warehouses")
def create_warehouse(service, groups, body):
    return service.create_warehouse(body.get("name"), body.get("location")), 201


@route("GET", r"/v1/warehouses")
def list_warehouses(service, groups, body):
    return service.list_warehouses(), 200


@route("POST", r"/v1/products")
def create_product(service, groups, body):
    return service.create_product(body.get("name"), body.get("unit")), 201


@route("GET", r"/v1/products")
def list_products(service, groups, body):
    return service.list_products(), 200


@route("POST", r"/v1/stock")
def add_stock(service, groups, body):
    r = service.add_stock(
        body.get("warehouse_id"), body.get("product_id"),
        body.get("quantity", 0), body.get("threshold"),
    )
    return r, 201


@route("POST", r"/v1/stock/adjustments")
def adjust_stock(service, groups, body):
    r = service.adjust_stock(
        body.get("warehouse_id"), body.get("product_id"),
        body.get("change_type"), body.get("amount"),
        body.get("reason"), body.get("actor", "system"),
        body.get("idempotency_key"),
    )
    return r, 201


@route("GET", r"/v1/stock/([^/]+)/([^/]+)")
def get_stock(service, groups, body):
    wid, pid = groups
    return service.get_stock(wid, pid), 200


@route("GET", r"/v1/products/([^/]+)/stock")
def stock_by_product(service, groups, body):
    return service.get_stock_by_product(groups[0]), 200


@route("GET", r"/v1/warehouses/([^/]+)/stock")
def stock_by_warehouse(service, groups, body):
    return service.get_stock_by_warehouse(groups[0]), 200


@route("PUT", r"/v1/thresholds/([^/]+)/([^/]+)")
def set_threshold(service, groups, body):
    wid, pid = groups
    return service.set_threshold(wid, pid, body.get("threshold")), 200


@route("GET", r"/v1/alerts")
def list_alerts(service, groups, body):
    return service.list_alerts(), 200


@route("GET", r"/v1/audit")
def list_audit(service, groups, body):
    return service.list_audit(), 200
